// Üretilen dosya: tool/ozgun/uret.py. Coğrafya · Avrupa ve Rusya bölgesel coğrafyası (zor).
const ozGeography10Zor = <(String, String, List<String>, String)>[
  ('Bazı coğrafyacılar Avrupa-Asya sınırını Kafkas Dağları\'nın sırtından değil, bu dağların kuzeyindeki alçak bir çöküntü boyunca çizer. Bu çöküntü hangisidir?', 'Kuma-Manyç Çukuru', ['Fergana Vadisi', 'Turan Çöküntü Ovası', 'Kolhis Alçak Ovası'], 'Kuma-Manyç Çukuru, Hazar ile Azak Denizi arasında uzanan alçak bir oluktur ve bazı tanımlarda kıta sınırı olarak alınır. Bu tanıma göre Kafkaslar Asya\'da kalır.'),
  ('Turistlerin Avrupa\'nın en kuzey noktası diye ziyaret ettiği Nordkapp aslında anakarada değildir. Bunun nedeni aşağıdakilerden hangisidir?', 'Magerøya adlı bir adanın üzerinde yer alması', ['Svalbard Takımadası\'na bağlı bir burun olması', 'Rusya\'nın Kola kıyısında bulunması', 'Bir fiyordun içindeki yapay bir set olması'], 'Nordkapp, Norveç\'in kuzeyindeki Magerøya Adası\'ndadır. Anakaranın en kuzey ucu yakındaki Kinnarodden (Nordkinn) Burnu\'dur.'),
  ('İskoçya\'nın dağlık kuzeyi ile Norveç dağlarının yapısal benzerliği hangi ortak dağ oluşumuyla açıklanır?', 'Kaledonya orojenezi', ['Alp orojenezi', 'Hersinyen orojenezi', 'Pireneler orojenezi'], 'Paleozoyik başında gerçekleşen Kaledonya orojenezi İskoçya, İrlanda ve Norveç\'teki yaşlı dağları oluşturmuştur. Atlas Okyanusu açılınca bu kuşak parçalara ayrılmıştır.'),
  ('İsviçre\'deki Gotthard Geçidi ve altındaki tüneller ülkenin hangi iki kesimini birbirine bağlar?', 'Orta İsviçre ile İtalyanca konuşulan Ticino\'yu', ['Cenevre çevresi ile Fransızca konuşulan Jura\'yı', 'Bern ile Romanşça konuşulan Graubünden\'i', 'Basel ile Almanca konuşulan Zürih\'i'], 'Gotthard, Uri kantonundaki Ren-Reuss vadileri ile güneydeki Ticino\'yu birbirine bağlayan, Kuzey-Güney Avrupa ulaşımında önemli bir Alp geçididir.'),
  ('Kuzeydoğu İtalya\'daki Dolomitler\'in adı nereden gelmektedir?', 'Kayacı tanımlayan jeolog Dolomieu\'nun adından', ['Bölgede yaşamış eski bir Kelt kabilesinin adından', 'Latince \'uzun dağ\' anlamına gelen bir sözcükten', 'Dağları ilk aşan Venedikli tüccarın soyadından'], 'Kalsiyum-magnezyum karbonatlı dolomit kayacını 18. yüzyılda tanımlayan Déodat de Dolomieu\'nun adı önce kayaca, sonra bu dağlara verilmiştir.'),
  ('Bulgaristan\'ın ve tüm Balkan Yarımadası\'nın en yüksek zirvesi olan Musala hangi dağ kütlesinde yer alır?', 'Rila Dağları', ['Rodop Dağları', 'Pirin Dağları', 'Balkan Dağları'], 'Yaklaşık 2.925 m olan Musala, Sofya\'nın güneyindeki Rila Dağları\'ndadır ve Balkanlar\'ın en yüksek noktasıdır.'),
  ('İtalya\'daki Apeninler\'in en yüksek zirvesi Corno Grande hangi dağ kütlesindedir?', 'Gran Sasso', ['Monte Amiata', 'Sila', 'Aspromonte'], 'Yaklaşık 2.912 m\'lik Corno Grande, Abruzzo bölgesindeki Gran Sasso d\'Italia kütlesinde yer alır.'),
  ('İskoçya\'yı kuzeydoğudan güneybatıya keserek Loch Ness gibi uzun ve dar gölleri barındıran oluk neyin sonucudur?', 'Büyük bir fay hattı boyunca aşınma', ['Bir akarsuyun menderes çizmesi', 'Bir volkan kalderasının çökmesi', 'Deniz düzeyinin yükselip çekilmesi'], 'Great Glen, büyük bir doğrultu atımlı fay boyunca gelişmiş, buzullarca derinleştirilmiş bir vadidir. Loch Ness bu oluğun içindedir.'),
  ('İskoçya\'da Great Glen boyunca dizilen gölleri birbirine bağlayarak kuzeydoğu ile güneybatı kıyıları arasında gemi geçişi sağlayan su yolu hangisidir?', 'Kaledonya Kanalı', ['Forth ve Clyde Kanalı', 'Manchester Gemi Kanalı', 'Kiel Kanalı'], '19. yüzyılda açılan Kaledonya Kanalı, Inverness ile Fort William arasındaki Loch Ness, Loch Oich ve Loch Lochy göllerini kanallarla birleştirir.'),
  ('Norveç\'in ve tüm Kuzey Avrupa\'nın en yüksek zirvesi olan Galdhøpiggen hangi dağ kütlesinde yer alır?', 'Jotunheimen', ['Lofoten', 'Dovrefjell', 'Hardangervidda'], 'Yaklaşık 2.469 m\'lik Galdhøpiggen, Norveç\'in güney-orta kesimindeki Jotunheimen kütlesindedir. Adı İskandinav mitolojisindeki devlerin yurdundan gelir.'),
  ('Finlandiya\'daki Punkaharju gibi, göller arasında kilometrelerce uzanan dar ve kıvrımlı kum-çakıl sırtlarına ne ad verilir?', 'Esker', ['Drumlin', 'Fiyort', 'Kum dili'], 'Eskerler, buzul tabanındaki tünellerde akan erime sularının bıraktığı kum ve çakılların oluşturduğu uzun sırtlardır. Finlandiya\'nın göl alanlarında çok yaygındır.'),
  ('İzlanda\'nın en büyük buzul kütlesi olan ve altında etkin yanardağlar barındıran buzul hangisidir?', 'Vatnajökull', ['Langjökull', 'Mýrdalsjökull', 'Hofsjökull'], 'Vatnajökull, Avrupa\'nın hacimce en büyük buzul örtülerinden biridir. Altındaki Grímsvötn gibi volkanlar buzu eriterek ani buzul taşkınları doğurabilir.'),
  ('1963\'te İzlanda\'nın güney kıyısı açığında bir deniz altı püskürmesiyle doğan ve bilim insanlarının canlıların yeni bir karaya yerleşmesini izlediği ada hangisidir?', 'Surtsey', ['Heimaey', 'Grímsey', 'Jan Mayen'], 'Surtsey 1963-1967 arasında süren püskürmelerle oluşmuştur. Yalnız araştırmacılara açık tutulan ada, ekolojik yerleşim sürecinin doğal bir laboratuvarı olmuştur.'),
  ('İzlanda\'nın güneyindeki, Orta Çağ\'da \'cehennemin kapısı\' olarak anılan ve en etkin yanardağlarından biri olan dağ hangisidir?', 'Hekla', ['Askja', 'Krafla', 'Snæfell'], 'Hekla, 874\'ten bu yana çok kez püskürmüş bir volkandır. Orta Çağ Avrupa\'sında cehennemin girişi olarak tanınmıştır.'),
  ('Napoli\'nin batısındaki Pozzuoli kentinde zeminin on yıllar içinde metrelerce yükselip alçalması hangi volkanik alanın etkinliğiyle açıklanır?', 'Campi Flegrei kalderası', ['Etna\'nın doğu yamacı', 'Stromboli\'nin kraterleri', 'Santorini\'nin kalderası'], 'Campi Flegrei, Napoli\'nin batısında büyük bir kalderadır. Altındaki magma ve gaz basıncındaki değişmeler \'bradisizm\' denen yavaş yer yükselmesi ve alçalmasına yol açar.'),
  ('Paris Havzası\'nda kenarlara doğru yükselen, iç içe geçmiş tabak gibi dizilmiş tortul katmanların oluşturduğu tek yanı dik sırtlara ne ad verilir?', 'Kuesta', ['Horst', 'Esker', 'Mesa'], 'Paris Havzası\'nda tortul katmanlar merkeze doğru hafifçe eğimlidir. Sert katmanlar aşınmaya direnerek dışa bakan yanı dik, içe bakan yanı yatık kuesta sırtları oluşturur.'),
  ('Ren Nehri\'nin rejiminin Avrupa\'nın birçok akarsuyuna göre daha dengeli olmasının temel nedeni nedir?', 'Yazın Alp buzullarının, kışın yağmurların beslemesi', ['Havzasının tamamen tek bir iklim tipinde olması', 'Akışını düzenleyen tek bir büyük göle dökülmesi', 'Yalnız yer altı kaynaklarından beslenmesi'], 'Ren\'in yukarı çığırı yazın kar ve buzul erimesiyle, aşağı çığırı ise kışın okyanusal yağışlarla beslenir. Bu iki kaynak birbirini dengeleyerek yıl boyu düzenli akış sağlar.'),
  ('Tuna Nehri\'nin geçtiği ya da sınırını oluşturduğu ülkeler arasında aşağıdakilerden hangisi yer almaz?', 'Slovenya', ['Slovakya', 'Hırvatistan', 'Moldova'], 'Tuna; Almanya, Avusturya, Slovakya, Macaristan, Hırvatistan, Sırbistan, Romanya, Bulgaristan, Moldova ve Ukrayna\'dan geçer ya da sınırlarını izler. Slovenya bu ülkeler arasında değildir.'),
  ('İber Yarımadası\'nın adının kökeni olduğu kabul edilen ve Akdeniz\'e dökülen akarsu hangisidir?', 'Ebro', ['Tajo', 'Guadalquivir', 'Júcar'], 'Antik Yunanlar ve Romalılar Ebro\'yu Iberus adıyla anar, çevresinde yaşayanlara İberler derdi. Yarımadanın adı buradan gelir.'),
  ('Belçika\'nın Anvers limanını Kuzey Denizi\'ne bağlayan ve ağız kısmı Hollanda topraklarından geçen akarsu hangisidir?', 'Schelde (Escaut)', ['Meuse (Maas)', 'Yser (IJzer)', 'Ren (Rijn)'], 'Anvers, Schelde\'nin halicine yakın kurulmuştur. Halicin denize açılan kısmı Hollanda\'da olduğundan iki ülke yüzyıllardır bu su yolunun kullanımı üzerine anlaşmalar yapmıştır.'),
  ('Litvanya\'nın en uzun akarsuyu olup Kür (Curonian) Lagünü\'ne dökülen nehir hangisidir?', 'Neman', ['Daugava', 'Narva', 'Pregel'], 'Neman (Nemunas) Beyaz Rusya\'dan doğar, Litvanya\'yı geçer ve Kür Kıstağı\'nın gerisindeki lagüne dökülür.'),
  ('Volga\'nın en büyük kolu olup Kazan\'ın aşağısında ona katılan ve Ural Dağları\'nın batı yamaçlarını drene eden akarsu hangisidir?', 'Kama', ['Oka', 'Vyatka', 'Belaya'], 'Kama, Volga\'nın debi bakımından en büyük koludur; Perm\'den geçer ve Kazan\'ın güneyinde Volga\'ya katılır.'),
  ('Nijniy Novgorod kentinde Volga Nehri\'ne katılan akarsu hangisidir?', 'Oka', ['Kama', 'Moskva', 'Don'], 'Oka, Orta Rusya Yaylası\'ndan doğar; Moskva Nehri\'ni de alarak Nijniy Novgorod\'da Volga\'ya katılır.'),
  ('Tamamen ahşaptan yapılmış 18. yüzyıl kiliseleriyle tanınan Kiji Adası, Avrupa\'nın ikinci büyük gölü olan hangi gölde yer alır?', 'Onega Gölü', ['Ladoga Gölü', 'Peipus Gölü', 'İlmen Gölü'], 'Rusya\'nın Karelya bölgesindeki Onega Gölü, Ladoga\'dan sonra Avrupa\'nın ikinci büyük gölüdür. Kiji Pogost ahşap kiliseleri UNESCO listesindedir.'),
  ('Dünyada yalnızca bir göl sisteminde yaşayan ve nesli tehlikede olan bir tatlı su fokunun yurdu olan Finlandiya\'nın en büyük gölü hangisidir?', 'Saimaa', ['İnari', 'Päijänne', 'Oulujärvi'], 'Saimaa, binlerce adası ve dolambaçlı kıyılarıyla Finlandiya\'nın en büyük gölüdür. Buzul Çağı\'ndan sonra burada kapalı kalan Saimaa foku yalnız bu gölde yaşar.'),
  ('Estonya ile Rusya arasındaki sınırın bir bölümünü oluşturan ve 1242\'deki \'Buz Muharebesi\' ile anılan göl hangisidir?', 'Peipus Gölü', ['Ladoga Gölü', 'Võrtsjärv Gölü', 'İlmen Gölü'], 'Peipus Gölü Estonya-Rusya sınırındadır. Novgorod Prensi Aleksandr Nevski\'nin Töton şövalyelerini yendiği savaş gölün donmuş yüzeyinde geçtiği için bu adla anılır.'),
  ('Borromeo Adaları\'nın bulunduğu ve kuzey ucu İsviçre\'nin Ticino kantonuna uzanan göl hangisidir?', 'Maggiore Gölü', ['Como Gölü', 'Garda Gölü', 'İseo Gölü'], 'Maggiore Gölü İtalya\'nın Piemonte ve Lombardiya bölgeleri ile İsviçre\'nin Ticino kantonu arasında paylaşılır.'),
  ('Kıyıları Arnavutluk, Kuzey Makedonya ve Yunanistan arasında paylaşılan göl hangisidir?', 'Büyük Prespa Gölü', ['Ohri Gölü', 'İşkodra Gölü', 'Doyran Gölü'], 'Büyük Prespa Gölü üç ülkenin sınırlarının kesiştiği yerdedir. Ohri yalnız Arnavutluk ile Kuzey Makedonya, İşkodra ise Karadağ ile Arnavutluk arasındadır.'),
  ('Avusturya ile Macaristan arasında paylaşılan, çok sığ ve tuzlumsu suyuyla Orta Avrupa\'nın bozkır gölü olarak bilinen göl hangisidir?', 'Neusiedl Gölü', ['Balaton Gölü', 'Attersee Gölü', 'Wolfgang Gölü'], 'Neusiedl Gölü\'nün ortalama derinliği iki metreyi bulmaz. Çevresindeki bozkır ve sazlıklar Avusturya-Macaristan ortak koruma alanıdır.'),
  ('Malta Cumhuriyeti\'ni oluşturan üç yerleşik ada hangi seçenekte doğru verilmiştir?', 'Malta, Gozo ve Comino', ['Malta, Lampedusa ve Pantelleria', 'Malta, Gozo ve Lipari', 'Malta, Comino ve Ustica'], 'Malta takımadasının yerleşik adaları Malta, Gozo ve Comino\'dur. Lampedusa, Pantelleria, Lipari ve Ustica İtalya\'ya aittir.'),
  ('Danimarka\'nın geri kalanından uzakta, İsveç\'in güney ucuna daha yakın olan Baltık adası hangisidir?', 'Bornholm', ['Gotland', 'Zelanda', 'Funen'], 'Bornholm, Kopenhag\'ın yaklaşık 150 km doğusunda, İsveç\'in Skåne kıyısının açığındadır ama Danimarka\'ya bağlıdır.'),
  ('Estonya\'nın en büyük adası hangisidir?', 'Saaremaa', ['Hiiumaa', 'Gotland', 'Muhu'], 'Saaremaa, Riga Körfezi\'nin girişinde yer alan Estonya\'nın en büyük adasıdır; Hiiumaa ise ikinci büyük adadır.'),
  ('Adriyatik\'in kuzeyinde, büyük bölümü Hırvatistan\'da, küçük kısımları Slovenya ve İtalya\'da olan üçgen biçimli yarımada hangisidir?', 'İstirya', ['Dalmaçya', 'Gargano', 'Pelješac'], 'İstirya Yarımadası, Trieste Körfezi ile Kvarner Körfezi arasındadır. Pula ve Rovinj gibi kentler Hırvatistan kesimindedir.'),
  ('Fransa\'nın Akitanya kıyısında Arcachon Körfezi\'nin girişindeki, Avrupa\'nın en yüksek kumulu olarak bilinen kum tepesi hangisidir?', 'Pilat Kumulu', ['Råbjerg Mile', 'Słowiński Kumulu', 'Kür Kumulu'], 'Pilat Kumulu yaklaşık 100 metreyi aşan yüksekliğiyle Avrupa\'nın en yüksek kumuludur. Atlas rüzgârlarının taşıdığı kumlar Landes kıyılarında geniş kumullar oluşturur.'),
  ('Litvanya ile Rusya\'nın Kaliningrad bölgesi arasında paylaşılan, Baltık\'ı bir lagünden ayıran yaklaşık 100 km\'lik ince kum dili hangisidir?', 'Kür Kıstağı', ['Hel Yarımadası', 'Jutland Kıstağı', 'Vistül Kıstağı'], 'Kür (Curonian) Kıstağı, yüksek kumullarıyla UNESCO listesindedir ve Kür Lagünü\'nü Baltık\'tan ayırır.'),
  ('Yazın Ege Denizi\'nde kuzeyden düzenli ve kuvvetli esen, antik dönemden beri yelkencilerin bildiği rüzgâra Yunanca ne ad verilir?', 'Meltemi', ['Sirocco', 'Mistral', 'Bora'], 'Meltemi, yazın Balkanlar üzerindeki yüksek basınç ile güneydoğudaki alçak basınç arasında oluşan, açık ve kuru havada esen kuzey rüzgârıdır.'),
  ('Bavyera\'da Alpler\'den inen sıcak ve kuru föhn rüzgârının estiği günlerde Münih\'ten Alpler\'in olağandışı yakın ve net görünmesinin nedeni nedir?', 'Alçalan havanın ısınıp kurumasıyla bulutların dağılması', ['Rüzgârın Sahra\'dan getirdiği ince tozun ışığı kırması', 'Havadaki nemin yoğuşarak alçak ve ince bir sis oluşturması', 'Kuzeyden gelen soğuk havanın tozları yere çökertmesi'], 'Föhn sırasında dağdan inen hava adyabatik olarak ısınır ve bağıl nemi düşer. Bulutlar dağılır, görüş mesafesi artar ve dağlar çok yakın görünür.'),
  ('Sırbistan\'da Demir Kapı\'dan Tuna vadisi boyunca Belgrad\'a doğru esen soğuk ve sert güneydoğu rüzgârının adı nedir?', 'Koşava', ['Bora', 'Mistral', 'Föhn'], 'Koşava, kışın Karpatlar\'ın doğusundaki yüksek basınç alanından Tuna vadisine sıkışarak giren soğuk bir rüzgârdır.'),
  ('Hollanda\'da Zuiderzee körfezini 1932\'de denizden ayırarak tatlı su gölü IJsselmeer\'in oluşmasını sağlayan yapı hangisidir?', 'Afsluitdijk seti', ['Oosterschelde barajı', 'Maeslant seti', 'Kiel Kanalı'], 'Yaklaşık 32 km uzunluğundaki Afsluitdijk, Zuiderzee\'yi Wadden Denizi\'nden ayırmıştır. Körfezin içi zamanla tatlanarak IJsselmeer adını almış, bir kısmı polderlere dönüştürülmüştür.'),
  ('Tümüyle eski Zuiderzee\'nin kurutulmasıyla kazanılmış topraklar üzerinde kurulan Hollanda ili hangisidir?', 'Flevoland', ['Zeeland', 'Friesland', 'Groningen'], 'Flevoland 1986\'da kurulan en genç Hollanda ilidir. Almere ve Lelystad gibi kentleri 20. yüzyılda kurutulan polderler üzerindedir.'),
  ('Kuzey Almanya\'nın orta yükseklikteki dağlarından Harz\'ın en yüksek ve efsanelerde cadıların toplandığı yer olarak anılan zirvesi hangisidir?', 'Brocken', ['Feldberg', 'Zugspitze', 'Fichtelberg'], 'Brocken, Harz Dağları\'nın en yüksek noktasıdır ve Goethe\'nin Faust\'undaki Walpurgis Gecesi sahnesiyle ün kazanmıştır. Feldberg ise Kara Orman\'ın en yüksek zirvesidir.'),
  ('Kuzey Almanya\'da kumlu buzul toprakları üzerinde süpürge çalılarıyla (funda) kaplı geniş açık alanlarıyla tanınan bölge hangisidir?', 'Lüneburg Fundalığı', ['Kara Orman', 'Spreewald', 'Eifel'], 'Lüneburg Fundalığı, Hamburg ile Hannover arasında, Buzul Çağı\'nın bıraktığı verimsiz kumlu topraklar üzerinde gelişmiş bir fundalık alandır.'),
  ('Dresden\'in güneydoğusunda Elbe\'nin kumtaşı platoyu yararak oluşturduğu, kule biçimli kayalıklarıyla tanınan bölgeye ne ad verilir?', 'Saksonya İsviçresi', ['Franken İsviçresi', 'Bohemya Ormanı', 'Cevher Ovası'], 'Saksonya İsviçresi\'ndeki Bastei gibi kumtaşı kuleleri, Elbe ve kollarının yumuşak kumtaşını aşındırmasıyla oluşmuştur.'),
  ('Fransa\'nın güneybatısındaki Landes bölgesinde 19. yüzyılda bataklıkları kurutmak ve kumulları sabitlemek için geniş ölçüde dikilen ağaç türü hangisidir?', 'Sahil çamı', ['Kayın', 'Meşe', 'Kızılağaç'], 'Landes ormanı büyük ölçüde sahil çamından (Pinus pinaster) oluşan, insan eliyle kurulmuş geniş bir ormandır. Ağaçlar kumul hareketini durdurmuş ve bölgeyi ekonomik olarak canlandırmıştır.'),
  ('Doğu İngiltere\'de Cambridge\'in kuzeyinde, 17. yüzyıldan itibaren bataklıkların kanallarla kurutulmasıyla tarıma açılan alçak ova hangisidir?', 'Fens', ['Broads', 'Weald', 'Downs'], 'Fens, Wash Körfezi çevresindeki eski turba ve kil bataklıklarıdır. Hollandalı mühendislerin de katkısıyla kurutulmuş, İngiltere\'nin en verimli tarım alanlarından birine dönüşmüştür.'),
  ('Güney İngiltere\'de Dorset ve Devon kıyısında, kayalıklarında üç jeolojik zamanın katmanları ve zengin fosiller görüldüğü için UNESCO listesine giren kıyı hangisidir?', 'Jura Kıyısı', ['Altın Kıyı', 'Beyaz Kıyı', 'Kelt Kıyısı'], 'Jurassic Coast\'ta Triyas, Jura ve Kretase dönemlerine ait yaklaşık 185 milyon yıllık kaya istifi kesintisiz izlenebilir.'),
  ('İrlanda\'nın batısında, çıplak kireçtaşı yüzeyleri, lapyaları ve mağaralarıyla tanınan karstik bölge hangisidir?', 'Burren', ['Connemara', 'Kerry', 'Wicklow'], 'Burren, kireçtaşının çözünmesiyle oluşmuş geniş çatlaklı kaya yüzeylerine sahiptir. Çatlaklarda Akdeniz ve Arktik bitkilerinin bir arada yetişmesiyle de ünlüdür.'),
  ('İrlanda adasının en yüksek zirvesi Carrauntoohil hangi dağ sırasındadır?', 'MacGillycuddy\'s Reeks', ['Wicklow Dağları', 'Mourne Dağları', 'Twelve Bens'], 'Yaklaşık 1.039 m\'lik Carrauntoohil, Kerry kontluğundaki MacGillycuddy\'s Reeks sırasındadır. Mourne Dağları ise Kuzey İrlanda\'dadır.'),
  ('Portekiz\'in en yüksek noktası, anakarada değil Atlas Okyanusu\'ndaki bir volkanik adadadır. Bu zirve hangisidir?', 'Azorlar\'daki Pico Dağı', ['Madeira\'daki Pico Ruivo', 'Kanarya\'daki Teide', 'Serra da Estrela\'daki Torre'], 'Yaklaşık 2.351 m\'lik Pico Dağı, Azorlar\'daki Pico Adası\'nın volkanik konisidir. Anakaranın en yüksek noktası Serra da Estrela\'daki Torre yaklaşık 1.993 m\'dir.'),
  ('Guadalquivir\'in ağzında, Avrupa ile Afrika arasında göç eden kuşlar için önemli bir durak olan İspanyol ulusal parkı hangisidir?', 'Doñana', ['Ordesa', 'Teide', 'Picos de Europa'], 'Doñana Ulusal Parkı, Guadalquivir deltasındaki bataklıklar, kumullar ve lagünlerden oluşur ve UNESCO Dünya Mirası listesindedir.'),
  ('Sınırları tamamen İtalya topraklarında kalan en yüksek Alp zirvesi olan ve çevresinde İtalya\'nın ilk ulusal parkı kurulan dağ hangisidir?', 'Gran Paradiso', ['Monte Rosa', 'Mont Blanc', 'Matterhorn'], 'Mont Blanc, Monte Rosa ve Matterhorn sınır dağlarıdır. Yaklaşık 4.061 m\'lik Gran Paradiso ise tamamen İtalya\'dadır; adını taşıyan park 1922\'de kurulmuştur.'),
  ('Slovenya\'daki Postojna Mağarası\'nın karanlık sularında yaşayan, gözleri körelmiş ve derisi pembe-beyaz olan mağara canlısı hangisidir?', 'Olm', ['Kör mağara balığı', 'Mağara yarasası', 'Mağara örümceği'], 'Proteus anguinus adlı olm, Dinar karstının yer altı sularına özgü bir semenderdir. Işıksız ortama uyum sağladığı için gözleri körelmiş, derisi pigmentsizdir.'),
  ('Karadağ\'daki Kotor Körfezi çoğu zaman fiyorda benzetilir. Bilimsel olarak gerçek bir fiyort sayılmamasının nedeni nedir?', 'Akarsu vadisinin denizle dolmasıyla oluşması', ['Kıyılarının tümüyle geniş kumullarla kaplı olması', 'Körfezin çökmüş bir volkan kalderası olması', 'Denizle hiçbir doğal bağlantısının bulunmaması'], 'Fiyortlar buzulların oyduğu vadilerin denizle dolmasıyla oluşur. Kotor Körfezi ise karstik dağlar arasındaki akarsu vadilerinin deniz düzeyi yükselince sular altında kalmasıyla oluşmuş bir ria sayılır.'),
  ('Hırvatistan\'ın Adriyatik kıyısını ikiye bölen, Bosna-Hersek\'in denize açılan tek kısa kıyısının bulunduğu kasaba hangisidir?', 'Neum', ['Split', 'Zadar', 'Bar'], 'Bosna-Hersek\'in yaklaşık 20 km\'lik kıyısı Neum çevresindedir. Bu kıyı şeridi Dubrovnik\'i Hırvatistan\'ın geri kalanından kara bağlantısı açısından ayırır.'),
  ('Arnavutluk, Karadağ ve Kosova arasında uzanan, Dinar sisteminin en yüksek ve en sarp kesimlerinden olan ve \'Lanetli Dağlar\' diye de anılan sıra hangisidir?', 'Prokletiye', ['Pindus Dağları', 'Rodop Dağları', 'Şar Dağları'], 'Prokletiye, Balkanlar\'ın en az erişilebilen dağlarındandır. Buzul şekilleri ve keskin kireçtaşı sırtlarıyla tanınır.'),
  ('Ron (Rhône) Nehri\'nin kaynağını oluşturan buzul hangi İsviçre kantonundadır?', 'Valais', ['Ticino', 'Graubünden', 'Bern'], 'Ron, Valais kantonundaki Ron Buzulu\'ndan doğar, vadisi boyunca batıya akarak Cenevre Gölü\'ne girer.'),
  ('Kraków yakınlarında yüzyıllardır işletilen ve yer altındaki galerilerinde tuzdan oyulmuş şapelleriyle tanınan maden hangisidir?', 'Wieliczka', ['Bochnia', 'Ostrava', 'Katowice'], 'Wieliczka tuz madeni 13. yüzyıldan beri işletilmiştir. İçindeki tuz heykelleri ve şapeller nedeniyle UNESCO listesindedir.'),
  ('Macaristan\'da Balaton\'un batısında yer alan ve kışın bile suyu ılık kaldığı için yıl boyu yüzülebilen doğal termal göl hangisidir?', 'Hévíz Gölü', ['Velence Gölü', 'Tisza Gölü', 'Fertő Gölü'], 'Hévíz Gölü, tabanındaki sıcak kaynaklardan beslenir. Dünyanın yüzülebilen en büyük doğal termal göllerinden biri olarak bilinir.'),
  ('Romanya\'nın en yüksek zirvesi Moldoveanu hangi dağ grubundadır?', 'Fagaraş Dağları', ['Apuseni Dağları', 'Bucegi Dağları', 'Rodna Dağları'], 'Yaklaşık 2.544 m olan Moldoveanu, Güney Karpatlar\'ın (Transilvanya Alpleri) bir parçası olan Fagaraş Dağları\'ndadır.'),
  ('Estonya ile Rusya arasındaki sınırın bir bölümünü oluşturan ve iki yakasında karşılıklı kaleler bulunan akarsu hangisidir?', 'Narva', ['Daugava', 'Neman', 'Gauja'], 'Narva Nehri, Peipus Gölü\'nden Fin Körfezi\'ne akar. Estonya\'daki Narva kenti ile Rusya\'daki İvangorod kalesi karşı karşıyadır.'),
  ('Dünyanın en büyük kehribar yataklarının bulunduğu Sambia Yarımadası hangi bölgededir?', 'Rusya\'nın Kaliningrad bölgesinde', ['Danimarka\'nın Jutland bölgesinde', 'Polonya\'nın Mazurya bölgesinde', 'Estonya\'nın Saaremaa adasında'], 'Baltık kehribarı, eski çam ağaçlarının fosilleşmiş reçinesidir. En zengin yataklar Kaliningrad\'daki Sambia Yarımadası\'ndadır ve tarihî \'Kehribar Yolu\' Baltık\'ı Akdeniz\'e bağlamıştır.'),
  ('Moldova\'nın deniz ulaşımı için aşağıdakilerden hangisi doğrudur?', 'Denize kıyısı yok, Tuna\'da çok kısa bir kıyısı var', ['Karadeniz\'e uzun bir kıyısı ve büyük limanları vardır', 'Azak Denizi\'ne açılan önemli bir limanı bulunur', 'Baltık Denizi\'ne bir kanalla doğrudan bağlanır'], 'Moldova Romanya ile Ukrayna arasında kalan kara ile çevrili bir ülkedir. Giurgiulești\'deki birkaç yüz metrelik Tuna kıyısı ülkenin nehir yoluyla Karadeniz\'e çıkışını sağlar.'),
  ('Norveç\'te deniz yüzeyinden yaklaşık 600 metre yükselen düz tepeli \'Kürsü Kayası\' (Preikestolen) hangi fiyordun üzerindedir?', 'Lysefjord', ['Sognefjord', 'Geirangerfjord', 'Hardangerfjord'], 'Preikestolen, Stavanger yakınındaki Lysefjord\'un dik yamacında yer alan, buzul aşındırmasıyla biçimlenmiş bir kaya çıkıntısıdır.'),
  ('Güney Norveç\'te, yabani ren geyiği sürülerinin yaşadığı, Avrupa\'nın en geniş yüksek dağ platosu olarak bilinen alan hangisidir?', 'Hardangervidda', ['Jotunheimen', 'Finnmarksvidda', 'Dovrefjell'], 'Hardangervidda ortalama 1.100-1.200 m yükseltideki geniş ve ağaçsız bir platodur. Buzulların düzlediği bu yüzeyde çok sayıda göl bulunur.'),
  ('Finlandiya\'nın en yüksek noktası olan Halti için hangisi doğrudur?', 'Asıl zirve Norveç\'tedir; Fin tarafı yamaçta kalır', ['Ülkenin güneyinde, Helsinki yakınlarında bulunur', 'Sönmüş bir volkan konisinin tepesinde yer alır', 'Saimaa Gölü\'nün ortasındaki bir adada yükselir'], 'Halti\'nin asıl zirvesi Norveç topraklarındadır. Finlandiya\'nın en yüksek noktası, sınırdaki yaklaşık 1.324 m yükseltideki yamaçtır.'),
  ('Danimarka\'da Zelanda ile Funen adalarını birbirine bağlayan köprü ve tünel sistemi hangi boğazın üzerindedir?', 'Büyük Kuşak', ['Küçük Kuşak', 'Öresund', 'Skagerrak'], 'Büyük Kuşak (Storebælt) Zelanda ile Funen arasındaki boğazdır; Küçük Kuşak ise Funen\'i Jutland\'dan ayırır. Öresund Danimarka ile İsveç arasındadır.'),
  ('Jutland\'ın kuzey ucunda, Skagerrak ile Kattegat dalgalarının karşılaştığı kumsal burun hangi kasabayla anılır?', 'Skagen', ['Esbjerg', 'Aarhus', 'Aalborg'], 'Skagen\'in ucundaki Grenen kum dilinde iki denizin dalgalarının birbirine çarpması görülebilir.'),
  ('Andorra\'nın devlet başkanlığını geleneksel olarak birlikte yürüten iki \'eş prens\' kimlerdir?', 'Fransa Cumhurbaşkanı ve Urgell Piskoposu', ['İspanya Kralı ve Fransa Cumhurbaşkanı', 'Roma\'daki Papa ve İspanya Kralı', 'Monako Prensi ve Barselona Başpiskoposu'], 'Andorra\'da Orta Çağ\'dan kalma bir düzenle devlet başkanlığı Fransa\'nın devlet başkanı ile İspanya\'daki La Seu d\'Urgell piskoposu arasında paylaşılır.'),
  ('San Marino\'nun başkenti ve kaleleri hangi dağın üzerine kurulmuştur?', 'Titano Dağı', ['Vezüv Dağı', 'Gran Sasso', 'Monte Amiata'], 'San Marino, Apeninler\'in kuzeydoğu eteklerinde yükselen Titano Dağı\'nın sırtına kurulmuştur. Üç kulesi ülkenin simgesidir.'),
  ('Edinburgh Kalesi\'nin üzerine kurulduğu Castle Rock adlı kayalık tepe nasıl oluşmuştur?', 'Sönmüş bir volkanın sert bacası olarak', ['Bir buzul moreninin zamanla yığılmasıyla', 'Bir mercan resifinin denizden yükselmesiyle', 'Tebeşir katmanlarının dalgalarca aşınmasıyla'], 'Castle Rock yaklaşık 350 milyon yıl önceki bir volkanın lav bacasıdır. Buzul Çağı\'nda buzullar çevresini aşındırmış, sert bazalt ise yüksek bir tepe olarak kalmıştır.'),
  ('Avrupa\'da \'Galiçya\' adının iki ayrı bölge için kullanılmasıyla ilgili hangisi doğrudur?', 'Biri İspanya\'da, diğeri Polonya-Ukrayna arasındadır', ['İkisi de İspanya\'da, birbirine komşu iki ayrı bölgedir', 'Biri İskoçya\'da, diğeri İrlanda adasının batısındadır', 'İkisi de aynı bölgenin eski ve yeni adlarıdır'], 'İspanya\'daki Galiçya Atlas kıyısındaki Kelt izli bir bölgedir. Orta Avrupa\'daki Galiçya ise Kraków ile Lviv arasında kalan, bugün Polonya ve Ukrayna\'ya bölünmüş tarihî bölgedir.'),
  ('Batı Sibirya Ovası\'nda dünyanın en büyük bataklık alanlarından birinin oluşmasında hangi etkenler birlikte rol oynar?', 'Düzlük ve kuzeyde donuk kalan akarsuların taşması', ['Bölgenin sıcak ve çok yağışlı tropikal iklimde bulunması', 'Arazinin yüksek, kayalık ve geçirimsiz bir plato olması', 'Bölgeye Hint Okyanusu\'ndan bol muson yağışı gelmesi'], 'Ova neredeyse eğimsizdir; ayrıca güneyden kuzeye akan Ob\'un aşağı çığırı ilkbaharda hâlâ donuk olduğundan erime suları taşar. Altta yer yer donmuş toprak da suyun süzülmesini engeller.'),
  ('Rusya ile Gürcistan sınırında yükselen, Prometheus efsanesiyle de ilişkilendirilen sönmüş volkan hangisidir?', 'Kazbek', ['Elbruz', 'Ağrı', 'Demavend'], 'Yaklaşık 5.047 m\'lik Kazbek, Büyük Kafkasların orta kesimindedir. Gürcü Askerî Yolu\'nun geçtiği Darial Geçidi bu dağın yakınındadır.'),
  ('Altay ile Baykal Gölü arasında, Moğolistan sınırı boyunca uzanan ve Yenisey\'in kaynak bölgesini oluşturan dağlar hangisidir?', 'Sayan Dağları', ['Verhoyansk Dağları', 'Çerski Dağları', 'Sihote-Alin Dağları'], 'Batı ve Doğu Sayan dağları Güney Sibirya\'dadır. Büyük ve Küçük Yenisey bu dağlardan doğarak Tuva\'da birleşir.'),
  ('Kamçatka\'da yükselen ve Avrasya\'nın en yüksek etkin yanardağı olarak bilinen volkan hangisidir?', 'Klyuçevskaya Sopka', ['Elbruz', 'Avaçinski', 'Kazbek'], 'Yaklaşık 4.750 m yüksekliğindeki Klyuçevskaya Sopka, Kamçatka\'nın sık püsküren stratovolkanlarındandır. Elbruz ve Kazbek ise etkinliğini yitirmiş sayılır.'),
  ('Baykal Gölü\'ne gelen suyun yaklaşık yarısını taşıyan ve Moğolistan\'dan doğan akarsu hangisidir?', 'Selenga', ['Angara', 'İrtiş Nehri', 'Amur Nehri'], 'Selenga Moğolistan\'dan doğar, Rusya\'nın Buryatya bölgesinde geniş bir delta oluşturarak Baykal\'a dökülür ve gölün en büyük besleyicisidir.'),
  ('Yenisey Nehri\'nin doğu yakasından katılan kolların batı yakasındakilerden çok daha uzun ve gür olmasının nedeni nedir?', 'Doğudaki geniş Orta Sibirya Platosu\'ndan beslenmesi', ['Batı yakasının tümüyle kumul çölleriyle kaplı olması', 'Doğu yakasında büyük buzulların yıl boyu erimesi', 'Batı yakasının Ural Dağları\'nın yamaçlarıyla kapanması'], 'Yenisey, Batı Sibirya Ovası ile Orta Sibirya Platosu\'nun sınırını izler. Angara ve Tunguska nehirleri gibi büyük kollar doğudaki geniş platodan gelir.'),
  ('Lena Nehri kıyısında yüzlerce metre yükselen, aşınmış kireçtaşı ve dolomitten oluşan kule biçimli kayalıklar hangi adla UNESCO listesindedir?', 'Lena Sütunları', ['Krasnoyarsk Sütunları', 'Ural Taşları', 'Yakut Kuleleri'], 'Lena Sütunları, Kambriyen yaşlı karbonat kayaçların sert iklimde donma-çözülme ve akarsu aşındırmasıyla parçalanmasıyla oluşmuştur.'),
  ('Kuzeydoğu Sibirya\'da Doğu Sibirya Denizi\'ne dökülen ve havzası Sovyet döneminde çalışma kamplarıyla anılan akarsu hangisidir?', 'Kolima', ['Lena', 'Anadır Nehri', 'Yana Nehri'], 'Kolima Nehri Doğu Sibirya\'nın en büyük akarsularındandır. Havzasındaki altın madenleri 20. yüzyılda zorla çalıştırma kamplarıyla işletilmiştir.'),
  ('Amur Nehri Rusya-Çin sınırını izledikten sonra hangi kentten geçerek Pasifik kıyısındaki Tatar Boğazı\'na ulaşır?', 'Nikolayevsk-na-Amure', ['Vladivostok', 'Magadan', 'Petropavlovsk'], 'Amur, Habarovsk\'tan sonra tümüyle Rusya topraklarında kuzeydoğuya akar ve Nikolayevsk-na-Amure yakınında Okhotsk Denizi ile Japon Denizi arasındaki Tatar Boğazı\'na dökülür.'),
  ('Novaya Zemlya ile Severnaya Zemlya takımadaları arasında kalan ve Yamal ile Taymır yarımadalarının kıyılarını yıkayan Arktik denizi hangisidir?', 'Kara Denizi', ['Barents Denizi', 'Laptev Denizi', 'Çukçi Denizi'], 'Kara Denizi batıda Novaya Zemlya, doğuda Severnaya Zemlya ile sınırlanır. Yılın büyük bölümünde buzla kaplıdır.'),
  ('Beyaz Deniz\'deki, Orta Çağ\'dan kalma manastır kompleksiyle UNESCO listesinde yer alan takımada hangisidir?', 'Solovetski Adaları', ['Kuril Adaları', 'Komutan Adaları', 'Yeni Sibirya Adaları'], 'Solovetski Adaları\'ndaki manastır 15. yüzyılda kurulmuştur. Sert kuzey koşullarında yapılmış bu yapılar Rus kuzeyinin önemli dinî ve kültürel merkezi olmuştur.'),
  ('Baykal Gölü\'nün en büyük adası hangisidir?', 'Olhon', ['Kiji', 'Valaam', 'Sahalin'], 'Olhon Adası Baykal\'ın batı kıyısına yakın, yaklaşık 70 km uzunluğunda bir adadır. Buryatlar için kutsal sayılan Şaman Kayası bu adadadır.'),
  ('Kuzey Ural\'ın batı yamaçlarından doğup Komi Cumhuriyeti\'ni geçerek Barents Denizi\'ne dökülen akarsu hangisidir?', 'Peçora', ['Mezen', 'Kuzey Dvina', 'Kama'], 'Peçora, Avrupa Rusyası\'nın kuzeydoğusundaki büyük akarsudur. Havzası tayga ve tundra ile kaplıdır ve Barents Denizi\'nin Peçora Körfezi\'ne dökülür.'),
  ('Kamçatka\'nın merkezi Petropavlovsk-Kamçatski için hangisi doğrudur?', 'Kente karayolu ya da demiryoluyla ulaşılamaz', ['Trans-Sibirya Demiryolu\'nun doğudaki son durağıdır', 'Bir göl kıyısında, yarımadanın iç kesiminde kurulmuştur', 'Kışın tamamen buzla kaplanan kapalı bir limandır'], 'Petropavlovsk-Kamçatski\'ye yalnız hava ve deniz yoluyla ulaşılabilir. Kent Avaça Körfezi kıyısında, etkin volkanların eteğindedir.'),
  ('Moskova\'nın tarihsel olarak Rus devletinin merkezi olmasında hangi konum özelliği etkili olmuştur?', 'Büyük akarsu havzalarının buluştuğu yerde olması', ['Karadeniz kıyısında korunaklı bir liman kenti olması', 'Ural Dağları\'nın doğal koruması altında bulunması', 'Kuzey Buz Denizi\'ne açılan bir halicin başında olması'], 'Moskova, Orta Rusya\'da büyük akarsu havzalarının birbirine yaklaştığı bir alanda kurulmuştur. Kısa taşıma yollarıyla bu havzalar arasında ticaret yapılabilmesi kentin güçlenmesini sağlamıştır.'),
  ('Moskova ile St. Petersburg arasındaki Valday Tepeleri\'nden doğup Baltık Denizi\'ne ulaşan akarsu hangisidir?', 'Batı Dvina (Daugava)', ['Neman (Nemunas)', 'Vistül (Wisła)', 'Narva Nehri'], 'Valday Tepeleri Avrupa Rusyası\'nın su bölümü çizgisidir. Buradan doğan Batı Dvina Beyaz Rusya ve Letonya\'yı geçerek Riga\'da Baltık\'a dökülür.'),
  ('Rusya\'da Onega Gölü\'nü Beyaz Deniz\'e bağlayan ve 1930\'larda zorla çalıştırılan mahkûmlarca yapılan kanal hangisidir?', 'Beyaz Deniz-Baltık Kanalı', ['Volga-Don Kanalı', 'Moskova (Moskva-Volga) Kanalı', 'Kiel Kanalı'], 'Belomorkanal adıyla da bilinen bu kanal, Onega Gölü üzerinden Baltık\'ı Beyaz Deniz\'e bağlar. Yapımında on binlerce mahkûm hayatını kaybetmiştir.'),
  ('Çukçi Denizi\'nde yer alan, kutup ayılarının yoğun olarak yavruladığı ve yünlü mamutların en son yaşadığı yer olarak bilinen ada hangisidir?', 'Vrangel Adası', ['Sahalin Adası', 'Kolguyev Adası', 'Bering Adası'], 'Vrangel Adası\'nda küçük boylu mamut topluluklarının yaklaşık 4.000 yıl öncesine kadar yaşadığı belirlenmiştir. Ada bugün doğal koruma alanıdır.'),
  ('Danimarka asıllı kâşif Vitus Bering\'in 1741\'de öldüğü ve bugün adını taşıyan adanın bulunduğu, Kamçatka\'nın doğusundaki takımada hangisidir?', 'Komutan Adaları', ['Kuril Adaları', 'Aleut Adaları', 'Şantar Adaları'], 'Komutan Adaları, Kamçatka ile Aleut zinciri arasındadır. Bering\'in seferinde mürettebatın kışladığı ada Bering Adası adını almıştır.'),
  ('Kuzey Ural\'ın batı yamaçlarında yer alan ve Avrupa\'nın insan eliyle en az bozulmuş en geniş ormanlarından biri olarak UNESCO listesine giren alan hangisidir?', 'Komi Bakir Ormanları', ['Białowieża Ormanı', 'Kara Orman', 'Karelya Ormanları'], 'Komi Bakir Ormanları, tayga ve tundranın büyük ölçüde bozulmadan kaldığı geniş bir alandır ve 1995\'te Dünya Mirası listesine alınmıştır.'),
  ('Rusya\'nın Uzak Doğusunda, Japon Denizi\'ne paralel uzanan ve nesli tehlikedeki Amur kaplanının yaşadığı dağ sırası hangisidir?', 'Sihote-Alin', ['Verhoyansk', 'Çerski', 'Sayan'], 'Sihote-Alin dağlarının muson etkili ormanlarında hem kuzey hem güney türleri bir arada yaşar. Amur (Sibirya) kaplanının en önemli yaşam alanıdır.'),
  ('Kafkasların kuzey yamaçlarından doğup Vladikavkaz\'dan geçen ve Hazar Denizi\'ne dökülen akarsu hangisidir?', 'Terek', ['Kuban', 'Kura', 'Aras Nehri'], 'Terek, Kazbek çevresinden doğar, Darial Geçidi\'nden Kuzey Osetya\'ya çıkar ve Dağıstan\'da bir deltayla Hazar\'a dökülür.'),
  ('Macaristan\'ın güneyindeki Szeged kenti hangi akarsuyun kıyısındadır?', 'Tisa (Tisza)', ['Tuna', 'Drava (Dráva)', 'Mur (Mura)'], 'Tisa, Macar Ovası\'nı kuzeyden güneye geçer. Szeged, Tisa ile Maros\'un birleştiği yere yakın kurulmuştur.'),
  ('Slovenya\'nın başkenti Ljubljana\'nın kuruluş yeri için hangisi doğrudur?', 'Alpler ile karst arasında, Ljubljanica kıyısında', ['Adriyatik kıyısında, Kotor Körfezi\'nin iç ucunda', 'Tuna\'nın Demir Kapı boğazından çıktığı yerde', 'Panonya Ovası\'nda, Tisa ile Tuna\'nın arasında'], 'Ljubljana, Alpler\'in güneydoğu eteği ile Dinar karstının kuzey ucu arasındaki Ljubljana Havzası\'nda, Ljubljanica Nehri\'nin iki yakasına kurulmuştur.'),
  ('Kuzey İrlanda\'nın merkezi Belfast hangi akarsuyun denize döküldüğü körfezde kurulmuştur?', 'Lagan', ['Shannon', 'Liffey', 'Boyne'], 'Belfast, Lagan Nehri\'nin Belfast Lough adlı körfeze döküldüğü yerde gelişmiştir. Bu körfez kenti gemi yapımcılığıyla ünlü bir liman yapmıştır.'),
  ('Madrid\'in içinden geçen ve kentin büyüklüğüne göre küçük bir akarsu olarak bilinen nehir hangisidir?', 'Manzanares', ['Tajo', 'Ebro', 'Guadalquivir'], 'Manzanares, Guadarrama dağlarından doğup Madrid\'den geçer ve Jarama üzerinden Tajo havzasına bağlanır. Tajo ise Madrid\'in güneyinden, Toledo\'dan geçer.'),
  ('Romanya\'nın başkenti Bükreş, Tuna Nehri\'ne göre nerededir?', 'Tuna\'nın kuzeyinde, Eflak Ovası\'nda kıyıdan uzakta', ['Tuna\'nın tam kıyısında, Bulgaristan\'ın tam karşısında', 'Tuna deltasının içinde, Karadeniz kıyısında', 'Tuna\'nın güneyinde, Balkan Dağları\'nın eteğinde'], 'Bükreş, Tuna\'nın yaklaşık 60 km kuzeyinde, onun bir alt kolu olan Dâmbovița kıyısında kurulmuştur. Tuna kıyısındaki Bulgaristan sınırına bu nedenle doğrudan bitişik değildir.'),
  ('İzlanda\'nın kuzeydoğusunda, buzul kaynaklı Jökulsá á Fjöllum üzerinde yer alan ve debisiyle Avrupa\'nın en güçlü şelalelerinden sayılan şelale hangisidir?', 'Dettifoss', ['Gullfoss', 'Skógafoss', 'Seljalandsfoss'], 'Dettifoss, Vatnajökull\'dan beslenen bir buzul akarsuyu üzerindedir; yaklaşık 44 m yükseklikten büyük miktarda su döker.'),
  ('Avusturya\'nın en yüksek şelalesi olan ve Hohe Tauern Ulusal Parkı\'nda üç basamakla yaklaşık 380 metre düşen şelale hangisidir?', 'Krimml Şelaleleri', ['Ren Şelalesi', 'Gavarnie Şelalesi', 'Staubbach Şelalesi'], 'Krimml Şelaleleri, Krimmler Ache akarsuyunun Salzburg eyaletinde üç basamakta toplam yaklaşık 380 m düşmesiyle oluşur.'),
  ('Fransız Pireneleri\'nde, buzulların oyduğu dev bir sirkin duvarından dökülen ve Avrupa\'nın en yüksek şelalelerinden biri olan şelale hangisidir?', 'Gavarnie Şelalesi', ['Krimml Şelalesi', 'Gullfoss', 'Trümmelbach Şelalesi'], 'Cirque de Gavarnie, buzulların oyduğu amfitiyatro biçimli bir çanaktır. Duvarından düşen şelale yaklaşık 420 m yüksekliğindedir.'),
  ('Salzburg yakınlarındaki Werfen\'de bulunan ve dünyanın bilinen en büyük buz mağarası olarak tanıtılan mağara hangisidir?', 'Eisriesenwelt', ['Postojna', 'Škocjan', 'Dachstein Mamut Mağarası'], 'Eisriesenwelt (\'Buz devlerinin dünyası\') bir kireçtaşı mağarasıdır. Kışın giren soğuk havanın ilkbaharda sızan suyu dondurmasıyla girişe yakın bölümleri yıl boyu buzla kaplıdır.'),
  ('Slovenya\'daki Škocjan Mağaraları\'nı ünlü kılan özellik hangisidir?', 'Reka Nehri\'nin yer altında açtığı dev kanyon', ['Buzul Çağı insanlarına ait çok sayıda mağara resmi', 'Lavların soğumasıyla oluşmuş uzun bir lav tüpü olması', 'İçinde Avrupa\'nın en büyük kaya tuzu yataklarının bulunması'], 'Reka Nehri Kras platosunda yer altına girerek yüz metreyi aşan derinlikte büyük bir yer altı kanyonu açmıştır. Bu karst sistemi UNESCO listesindedir.'),
  ('Alpler\'in en eski ulusal parkı olarak 1914\'te kurulan park hangi ülkededir?', 'İsviçre', ['Avusturya', 'Fransa', 'İtalya'], 'İsviçre Ulusal Parkı Graubünden kantonundaki Engadin\'de kurulmuştur ve doğanın insan müdahalesi olmadan gelişmesine bırakıldığı sıkı bir koruma alanıdır.'),
  ('Pireneler\'in Fransa tarafında yer aldığı hâlde İspanya\'ya ait olan ve 1659 antlaşmasının \'köyler\' maddesindeki bir boşluk nedeniyle İspanya\'da kalan kasaba hangisidir?', 'Llívia', ['Andorra la Vella', 'Perpignan', 'Puigcerdà'], '1659 Pireneler Antlaşması\'yla bazı köyler Fransa\'ya bırakılmış, ancak Llívia kasaba sayıldığı için İspanya\'da kalmıştır. Bugün Fransız topraklarıyla çevrili bir eksklavdır.'),
  ('Ren Nehri kıyısında, tamamen İsviçre topraklarıyla çevrili olan Alman kasabası hangisidir?', 'Büsingen', ['Konstanz', 'Lörrach', 'Vaduz'], 'Büsingen am Hochrhein, Schaffhausen yakınında İsviçre ile çevrili bir Alman eksklavıdır. Gümrük bakımından İsviçre bölgesine dahil edilmiştir.'),
  ('Belçika ve Hollanda topraklarının birbirinin içine onlarca küçük parça hâlinde geçtiği, sınırın bazı evlerin içinden geçtiği kasaba hangisidir?', 'Baarle', ['Maastricht', 'Eupen', 'Vaals'], 'Baarle-Hertog (Belçika) ile Baarle-Nassau (Hollanda) Orta Çağ\'dan kalma karmaşık mülkiyet sınırları nedeniyle iç içe geçmiş çok sayıda enklav oluşturur.'),
  ('İsveç ile Finlandiya arasındaki sınırın kuzey bölümünü oluşturan ve Bothnia Körfezi\'ne dökülen akarsu hangisidir?', 'Torne', ['Kemi', 'Oulu Nehri', 'Lule Nehri'], 'Torne (Tornio) Nehri İsveç Laponyası\'ndan doğar ve ağzındaki Haparanda (İsveç) ile Tornio (Finlandiya) kentleri arasında sınır çizer.'),
  ('Hollanda\'nın Avrupa\'daki en yüksek noktası olan Vaalserberg\'i ilginç kılan özellik hangisidir?', 'Üç ülkenin sınırlarının kesiştiği noktada olması', ['Bir buzul moreninin kalıntısı olan tepenin üzerinde bulunması', 'Deniz düzeyinin altında kalan bir polderin ortasında olması', 'Kuzey Denizi\'ndeki bir adanın ortasında yükselmesi'], 'Yaklaşık 322 m\'lik Vaalserberg, Aachen yakınında üç ülkenin buluştuğu noktadadır. Hollanda\'nın Karayipler\'deki toprakları dahil edilirse en yüksek nokta Saba\'daki tepedir.'),
  ('Hazar Denizi\'nin kuzeybatısında yer alan ve halkının çoğunluğu Budist olduğu için Avrupa\'daki tek Budist çoğunluklu bölge sayılan Rus cumhuriyeti hangisidir?', 'Kalmukya', ['Dağıstan', 'Tataristan', 'Adıgey'], 'Kalmuklar 17. yüzyılda Batı Moğolistan\'dan Volga\'nın aşağı kesimlerine göç etmiş Moğol kökenli bir halktır. Başkenti Elista\'dır.'),
  ('Altay Dağları\'nın en yüksek zirvesi olan ve Rusya ile Kazakistan sınırında yükselen dağ hangisidir?', 'Beluha', ['Elbruz', 'Narodnaya', 'Klyuçevskaya Sopka'], 'Yaklaşık 4.506 m\'lik Beluha iki zirveli, buzullarla kaplı bir dağdır ve Sibirya\'nın en yüksek noktasıdır.'),
  ('Yenisey\'in kaynak kollarının birleştiği yerde kurulmuş ve \'Asya\'nın coğrafi merkezi\' anıtıyla tanınan kent hangisidir?', 'Kızıl', ['Abakan', 'Irkutsk', 'Barnaul'], 'Tuva Cumhuriyeti\'nin başkenti Kızıl, Büyük ve Küçük Yenisey\'in birleştiği yerdedir. Kentte Asya\'nın merkezini simgeleyen bir anıt bulunur.'),
  ('Volga Nehri\'nin Samara yakınında Jiguli Dağları\'nı dolanarak çizdiği büyük yay biçimli kıvrıma ne ad verilir?', 'Samara Luka', ['Volga Dirseği', 'Kazan Kavsi', 'Ural Kapısı'], 'Samarskaya Luka, Volga\'nın Jiguli Tepeleri\'ni çevreleyerek yaptığı geniş bir menderestir; içinde bir ulusal park bulunur.'),
  ('Volga üzerinde Tolyatti yakınında kurulan ve yüzey alanı bakımından Avrupa\'nın en büyük baraj gölü olarak bilinen rezervuar hangisidir?', 'Kuybışev Rezervuarı', ['Rybinsk Rezervuarı', 'Tsimlyansk Rezervuarı', 'Krasnoyarsk Rezervuarı'], 'Kuybışev Rezervuarı 1950\'lerde Jiguli hidroelektrik santralinin barajıyla oluşmuştur ve yaklaşık 6.000 km²\'lik alanıyla Avrupa\'nın en büyük yapay gölüdür.'),
  ('1940\'larda Volga üzerinde bir baraj gölü oluşturulurken Mologa adlı tarihî kasabanın tümüyle sular altında kaldığı rezervuar hangisidir?', 'Rybinsk Rezervuarı', ['Kuybışev Rezervuarı', 'Volgograd Rezervuarı', 'Kama Rezervuarı'], 'Rybinsk Rezervuarı Volga\'nın yukarı kesiminde kurulmuştur. Doldurulması sırasında Mologa kasabası ve yüzlerce köy boşaltılmıştır.'),
  ('Kutup dairesinin kuzeyinde, Peçora kömür havzası üzerinde Sovyet döneminde kurulan maden kenti hangisidir?', 'Vorkuta', ['Norilsk', 'Murmansk', 'Salehard'], 'Vorkuta, Komi Cumhuriyeti\'nin kuzeydoğusunda, Ural\'ın kutup kesimine yakın konumdadır ve kömür madenciliği için kurulmuştur.'),
  ('Okhotsk Denizi kıyısında kurulan ve Kolima bölgesinin altın madenlerine açılan kapı olan kent hangisidir?', 'Magadan', ['Vladivostok', 'Habarovsk', 'Anadır'], 'Magadan 1930\'larda Kolima\'nın maden ve kamp sistemine ikmal sağlamak için kurulmuştur. \'Kemikler Yolu\' denen Kolima karayolu buradan başlar.'),
  ('Rus devletinin en eski merkezlerinden Velikiy Novgorod, İlmen Gölü\'nden çıkıp Ladoga\'ya akan hangi nehrin kıyısındadır?', 'Volhov', ['Neva', 'Svir Nehri', 'Narva'], 'Novgorod, Volhov\'un İlmen Gölü\'nden çıktığı yere yakın kurulmuştur. Bu su yolu Orta Çağ\'da Baltık\'ı Dinyeper üzerinden Karadeniz\'e bağlayan ticaret yolunun parçasıydı.'),
  ('Orta Sibirya Platosu\'nun kuzeybatısında, Norilsk\'in güneydoğusunda yer alan ve derin kanyonları, şelaleleri ile UNESCO listesine giren bazalt platosu hangisidir?', 'Putorana Platosu', ['Ukok Platosu', 'Vitim Platosu', 'Stanovoy Platosu'], 'Putorana Platosu, kalın bazalt lav örtülerinden oluşur. Erişilmesi zor bu yüksek alanda kutup ve tayga ekosistemleri bozulmadan korunmuştur.'),
  ('İspanya ile Portekiz arasındaki sınırın en kuzeydeki kesimini oluşturan akarsu hangisidir?', 'Minho', ['Guadiana', 'Duero', 'Tajo'], 'Minho (İspanyolca Miño) Galiçya\'dan doğar ve son kesiminde iki ülke arasında sınır çizerek Atlas Okyanusu\'na dökülür. Güneydeki sınırın bir bölümünü ise Guadiana oluşturur.'),
  ('İspanya\'da Meseta platosunu güneydeki Guadalquivir (Endülüs) ovasından ayıran dağ sırası hangisidir?', 'Sierra Morena', ['Sierra Nevada', 'Kantabria Dağları', 'Sistema Ibérico'], 'Sierra Morena, Meseta\'nın güney kenarını oluşturur ve Guadalquivir vadisinin kuzey sınırını çizer. Sierra Nevada ise vadinin güneyindedir.'),
  ('İspanya\'nın Huelva bölgesinde, binlerce yıllık madencilik ve demir-bakır mineralleri nedeniyle suyu kırmızımsı ve çok asitli olan akarsu hangisidir?', 'Río Tinto', ['Guadalquivir', 'Guadiana', 'Segura'], 'Río Tinto (\'boyalı nehir\') havzasındaki sülfürlü cevherler suyu asitli ve demirce zengin yapar. Bölge en az 5.000 yıldır maden üretimiyle tanınır.'),
  ('İspanya\'nın Almería bölgesinde, yağışın çok az olması nedeniyle Avrupa\'nın gerçek çöllerinden biri sayılan ve western filmlerinin çekildiği alan hangisidir?', 'Tabernas', ['Bardenas', 'Monegros', 'Meseta'], 'Tabernas, Sierra Nevada ile çevre dağların yağış gölgesinde kalır; yıllık yağış çok düşüktür. Kurak ve aşınmış arazisi Amerikan çöllerine benzer.'),
  ('Roma\'nın güneydoğusundaki bataklıklar 1930\'larda kurutularak yeni kentlerin kurulduğu tarım alanlarına dönüştürülmüştür. Bu alan hangisidir?', 'Pontin Bataklıkları', ['Po Deltası', 'Venedik Lagünü', 'Maremma Kıyı Ovası'], 'Pontin Bataklıkları (Agro Pontino) yüzyıllar boyu sıtma kaynağıydı. 1930\'lardaki kurutma çalışmalarıyla Latina gibi yeni kentler kurulmuştur.'),
  ('Tamamı Almanya sınırları içinde kalan en büyük göl olan ve Mecklenburg göller bölgesinde yer alan göl hangisidir?', 'Müritz', ['Konstanz', 'Chiemsee', 'Ammersee'], 'Konstanz Gölü daha büyüktür ama üç ülke arasında paylaşılır. Müritz ise tümüyle Almanya\'da kalan en büyük göldür ve buzul kökenlidir.'),
  ('Berlin\'in güneydoğusunda, Spree Nehri\'nin yüzlerce kola ayrılarak oluşturduğu kanallar ağında ulaşımın geleneksel olarak sandallarla yapıldığı bölge hangisidir?', 'Spreewald', ['Schwarzwald', 'Odenwald', 'Bayerischer Wald'], 'Spreewald\'da Spree, Buzul Çağı\'ndan kalma düz bir vadide birçok kola ayrılır. Köyler arasındaki ulaşım uzun süre bu kanallar üzerinden yapılmıştır.'),
  ('Birleşik Krallık\'ın 1951\'de ilan edilen ilk ulusal parkı olan ve Penninler\'in güney ucunda yer alan alan hangisidir?', 'Peak District', ['Lake District', 'Snowdonia', 'Dartmoor'], 'Peak District, Manchester ile Sheffield arasındadır. Büyük kentlere yakınlığı nedeniyle halkın doğaya erişim hakkı hareketinin odağı olmuştur.'),
  ('Norveç\'e bağlı Jan Mayen Adası\'nda yükselen ve dünyanın en kuzeydeki etkin volkanlarından biri olan dağ hangisidir?', 'Beerenberg', ['Hekla', 'Galdhøpiggen', 'Katla'], 'Beerenberg, Grönland Denizi\'ndeki Jan Mayen Adası\'nın kuzey ucunu oluşturan, buzullarla kaplı bir stratovolkandır.'),
  ('Karadağ\'da yer alan ve derinliğiyle Avrupa\'nın en derin kanyonları arasında gösterilen kanyon hangi nehir tarafından açılmıştır?', 'Tara', ['Neretva', 'Drina', 'Morača'], 'Tara Kanyonu, Durmitor Ulusal Parkı içindedir ve yer yer 1.300 metreye yaklaşan derinliğe ulaşır. Tara daha sonra Piva ile birleşip Drina\'yı oluşturur.'),
  ('Sırbistan\'ın iç kesimlerini güneyden kuzeye kat ederek Belgrad\'ın doğusunda Tuna\'ya katılan akarsu hangisidir?', 'Büyük Morava', ['Sava', 'Drina', 'Tisa'], 'Büyük Morava, Batı ve Güney Morava\'nın birleşmesiyle oluşur. Vadisi, Orta Avrupa\'yı Selanik\'e bağlayan tarihî Morava-Vardar koridorunun parçasıdır.'),
  ('Polonya\'nın Baltık kıyısında, rüzgârın etkisiyle yılda birkaç metre ilerleyen hareketli kumullarıyla tanınan ulusal park hangisidir?', 'Słowiński Ulusal Parkı', ['Białowieża Ulusal Parkı', 'Tatra Ulusal Parkı', 'Bieszczady Ulusal Parkı'], 'Słowiński Ulusal Parkı Łeba yakınındadır. Buradaki kumullar denizden gelen rüzgârlarla iç kesime doğru ilerleyerek ormanları örter.'),
  ('Kırım Yarımadası\'nı anakaradan neredeyse ayıran, Azak Denizi\'nin batısındaki sığ ve çok tuzlu lagünler sistemi hangisidir?', 'Sivaş (Çürük Deniz)', ['Kerç Boğazı', 'Dinyeper Haliçi (Liman)', 'Kür (Curonian) Lagünü'], 'Sivaş, Arabat Kum Dili ile Azak Denizi\'nden ayrılan sığ lagünlerden oluşur. Yazın buharlaşma yüksek olduğundan suyu çok tuzludur ve kötü kokusuyla \'Çürük Deniz\' diye anılır.'),
  ('Bir öğrenci \'İzlanda\'nın tamamı kuzey kutup dairesinin kuzeyindedir\' diyor. Bu ifade için hangisi doğrudur?', 'Yanlıştır; daire yalnız kuzeydeki Grímsey Adası\'ndan geçer', ['Doğrudur; ülkenin tamamı kutup dairesinin kuzeyinde yer alır', 'Yanlıştır; İzlanda\'nın tamamı Yengeç Dönencesi\'nin güneyindedir', 'Doğrudur; ancak yalnızca Reykjavik bu kuşağın dışında kalır'], 'İzlanda anakarası kutup dairesinin hemen güneyinde kalır. Daire yalnız kuzey kıyısının açığındaki küçük Grímsey Adası\'ndan geçer.'),
  ('Viyana\'yı Graz ve Trieste yönüne bağlayan, 1854\'te açıldığında Alpler\'i aşan ilk dağ demiryolu sayılan ve UNESCO listesinde yer alan hat hangi geçitten geçer?', 'Semmering', ['Brenner', 'Gotthard', 'Simplon'], 'Semmering Demiryolu, Aşağı Avusturya ile Steiermark arasındaki geçidi çok sayıda viyadük ve tünelle aşar. Mühendislik başarısıyla Dünya Mirası listesindedir.'),
  ('İsviçre\'nin Valais kantonundaki Brig ile İtalya\'daki Domodossola arasında Alpler\'i tünelle geçmek isteyen bir tren yolcusu hangi geçidin altından geçer?', 'Simplon', ['Brenner', 'Semmering', 'Mont Cenis'], 'Simplon Tüneli, Ron vadisini İtalya\'nın Ossola vadisine bağlar ve Paris-Milano demiryolu hattının Alpler\'i aştığı noktadır.'),
  ('Galler, İskoçya\'nın kuzeybatısı, İrlanda\'nın batısı ve Bretanya\'da Kelt dillerinin İngilizce ve Fransızca karşısında daha uzun süre yaşamasında hangi coğrafi etken önemli rol oynamıştır?', 'Bu bölgelerin dağlık ve kıtanın batı kenarında kalması', ['Bu bölgelerin büyük ticaret yollarının kavşağında olması', 'Bu bölgelerin geniş ve verimli ovalarla kaplı olması', 'Bu bölgelerin büyük başkentlere en yakın yerler olması'], 'Batının engebeli ve uzak kıyı bölgeleri, merkezî yönetimlerin ve egemen dillerin etkisine daha geç açılmıştır. Bu kenar konum Kelt dillerinin korunmasını kolaylaştırmıştır.'),
  ('Rusya\'da tarımın büyük ölçüde St. Petersburg, Karadeniz kıyısı ve Novosibirsk arasında kalan \'tarım üçgeni\'nde yoğunlaşmasının nedeni nedir?', 'Kuzeyde aşırı soğuk, güneydoğuda kuraklık', ['Bu alanın ülkenin en yüksek dağlarını barındırması', 'Bu alanın dışında hiçbir akarsuyun bulunmaması', 'Bu alanın tümüyle kalın bir permafrost üzerinde olması'], 'Kuzeyde yetişme dönemi çok kısa, Orta Asya\'ya yakın güneydoğuda ise yağış yetersizdir. Sıcaklığın ve nemin tarıma yettiği alan bu üçgende toplanır.'),
  ('Kırmızı renkli \'terra rossa\' toprağı Avrupa\'da en çok hangi koşulda oluşur?', 'Akdeniz havzasında kireçtaşı üzerinde', ['Tayga ormanları altında', 'Okyanusal iklimin nemli ovalarında', 'Tundra kuşağının donmuş zemininde'], 'Terra rossa (kırmızı toprak), Akdeniz havzasında kireçtaşı üzerinde, demir oksit zenginliği nedeniyle kırmızı renkte oluşur.'),
  ('Sırbistan ve Romanya sınırında Tuna\'nın Karpatlar\'ı yararak geçtiği dar vadinin adı nedir?', 'Demirkapı (Demir Kapı) Geçidi', ['Kiel Geçidi', 'Brenner Geçidi', 'Kapıkule Geçidi'], 'Demirkapı, Tuna\'nın Güney Karpatlar ile Balkanlar arasındaki dar ve derin geçididir; hidroelektrik barajlarla tanınır.'),
  ('Çekya\'nın batısında yer alan, yaşlı ve aşınmış bir kıvrım kalıntısı olan yüksekliğin adı nedir?', 'Bohemya Masifi', ['Kara Orman', 'Ardenler', 'Skandik Kalkanı'], 'Bohemya Masifi, Çekya\'nın batısında yer alan yaşlı ve aşınmış kıvrım kalıntısı bir yüksekliktir.'),
  ('Bulgaristan\'dan doğup Yunanistan\'dan geçerek Ege Denizi\'ne dökülen akarsu hangisidir?', 'Struma', ['Drava', 'Vardar', 'Morava'], 'Struma (Strymonas) Bulgaristan\'dan Yunanistan\'a geçip Ege\'ye dökülür. Vardar da Ege\'ye ulaşır ama Kuzey Makedonya\'dan akar.'),
  ('Svalbard takımadasının en büyük adası olan Spitsbergen\'deki başlıca yerleşim merkezi hangisidir?', 'Longyearbyen', ['Tromsø', 'Reykjavik', 'Murmansk'], 'Longyearbyen Spitsbergen\'dedir ve dünyanın en kuzeydeki büyük kalıcı yerleşimlerinden biridir; ekonomisi kömür, bilim ve turizme dayanır.'),
  ('Kırım Yarımadası\'nı Karadeniz ile Azak Denizi arasında anakaraya bağlayan dar kara şeridine ne ad verilir?', 'Perekop Kıstağı', ['Kerç Boğazı', 'Kuzey Kıstağı', 'Tamanskiy Kıstağı'], 'Perekop Kıstağı yalnızca birkaç on kilometre genişliğindedir ve Kırım\'ı kuzeyden Ukrayna anakarasına bağlar.'),
  ('Ob Nehri\'nin en büyük kolu olan ve kaynaklarını Çin\'in Altay bölgesinde bulan akarsu hangisidir?', 'Irtış', ['Tobol', 'Angara', 'Çulım'], 'Irtış Çin\'de başlar, Kazakistan\'dan Rusya\'ya geçerek Ob\'a karışır. Ob-Irtış sistemi dünyanın uzun akarsu sistemlerindendir.'),
  ('Doğu Sibirya\'da Magadan bölgesinden akarak Doğu Sibirya Denizi\'ne dökülen akarsu hangisidir?', 'Kolıma', ['Lena', 'Amur', 'Anadır'], 'Kolıma Kuzeydoğu Sibirya\'nın büyük akarsularındandır ve altın madenciliğiyle anılan bölgeden geçer.'),
  ('Aşağıdaki akarsulardan hangisi Lena Nehri\'nin kolu değildir?', 'Çulım', ['Aldan', 'Vilyuy', 'Olyokma'], 'Çulım Ob havzasında yer alır. Aldan, Vilyuy ve Olyokma Lena\'ya katılan büyük kollardır.'),
  ('Hollanda\'da lale gibi soğanlı çiçeklerin yetiştirildiği geniş tarlalar kıyıdaki hangi toprak koşulundan yararlanır?', 'İyi drene olan kumul kökenli kumlu topraklardan', ['Donmuş ve turbalı tundra toprağından', 'Volkanik kül topraklarından', 'Kırmızı kireçtaşı topraklarından'], 'Haarlem-Leiden arasındaki kıyı kumullarının kumlu toprağı suyu iyi süzer; soğanlar çürümez ve bu bölgede lale tarımı yoğunlaşmıştır.'),
  ('Finlandiya\'nın güneyinde kıyıya paralel uzanan Salpausselkä sırtları nasıl oluşmuştur?', 'Çekilen buzul kenarında biriken moren yığılmasıyla', ['Volkanik lav akıntılarıyla', 'Rüzgârın taşıdığı kum yığınlarıyla', 'Levha çarpışmasıyla kıvrılan tabakalarla'], 'Son buzul çağının sonunda buz kenarı uzun süre aynı kuşakta durduğundan taşıdığı malzemeyi sırt halinde bırakmıştır.'),
  ('Moldova\'nın güneyinde, Türkçe konuşan Ortodoks Hristiyan Gagauzların yaşadığı özerk bölge hangisidir?', 'Gagauzya', ['Transdinyester', 'Besarabya', 'Bukovina'], 'Gagauzya Moldova\'nın güneyinde özel statülü bir özerk bölgedir ve Gagauzlar Türk dilinin bir lehçesini konuşur.'),
  ('Angara Nehri üzerindeki büyük baraj nedeniyle hidroelektrik üretimi ve alüminyum sanayisiyle öne çıkan Sibirya kenti hangisidir?', 'Bratsk', ['Omsk', 'Perm', 'Samara'], 'Bratsk\'taki baraj büyük miktarda elektrik üretir; bu ucuz enerji elektrik yoğun alüminyum eritme tesislerinin kurulmasını kolaylaştırmıştır.'),
  ('Rusya\'nın Çukotka Özerk Okrugu\'nun idari merkezi olan ve Bering Denizi\'ne açılan körfez kıyısındaki kent hangisidir?', 'Anadır', ['Magadan', 'Habarovsk', 'Yakutsk'], 'Anadır Rusya\'nın en uzak doğu kentlerinden biridir; Anadır Körfezi\'ne yakındır ve ulaşım çoğunlukla hava ve deniz yoluyla sağlanır.'),
  ('Birmingham, İngiltere\'nin iç kesiminde denize kıyısı olmadığı hâlde 18-19. yüzyılda önemli bir sanayi merkezi olmuştur. Bu durumu en iyi açıklayan etken hangisidir?', 'Çevresindeki kömür ve demir yataklarının kanal ağıyla taşınması', ['Büyük bir limanın bulunması', 'Kutup rüzgârlarının getirdiği zengin yağışlar', 'Volkanik toprakların tarıma uygunluğu'], 'Midlands bölgesinde kömür ve demir yakın yatakları, yoğun kanal ağıyla birleşince ağır sanayinin gelişmesini sağlamıştır.'),
  ('Mosel Nehri kıyısında yer alan ve Roma dönemine ait Porta Nigra kapısıyla ünlü Alman kenti hangisidir?', 'Trier', ['Bremen', 'Kassel', 'Rostock'], 'Trier, Almanya\'nın en eski kentlerinden biri sayılır ve Mosel vadisindeki üzüm bağlarıyla çevrilidir.'),
  ('Alpler\'in içinde, Isère Vadisi\'nde kurulmuş olan ve yüksek dağlarla çevrili Fransız kenti hangisidir?', 'Grenoble', ['Dijon', 'Reims', 'Nantes'], 'Grenoble Fransız Alpleri\'nin kucağında, Isère ile Drac\'ın kavuştuğu çukurda yer alır ve kış turizmi ile bilim merkezidir.'),
];
